protected void calculateRebateLine(TAMRebateLine _rebateLine, boolean _more)
{
    TAMRebateDeductionAmount preRebateAmount;
    preRebateAmount = rebateAmount;
    next calculateRebateLine(_rebateLine, _more);


    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        if (rebateDeal.RebateTypeGUP != TAMRebateTypeGUP::Standard)
        {
            real periodNumber = this.rebateDatePeriod.getPeriodSequence(rebateJournalTrans.parmRebateFromDate(), rebateJournalTrans.parmRebateToDate());
            preRebateAmount += GUPRebateAmortizationScheduleDetail::getSpecificPeriodAmount(_rebateLine, periodNumber) * this.getRebateLineRate(_rebateLine, _more);

            rebateAmount = preRebateAmount;
        }
    }
}
